/*
 * A183173  Ordering of the numbers in set S generated by these rules: 2 is in
 *          S, and if n is in S then floor(r*n) and floor(s*n) are in S, where
 *          r=sqrt(2) and s=r/(r-1).
 * https://oeis.org/A183173
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 1, u16 n <= 26, u32 n <= 7018, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: a(1)=2, then a(2)*s and a(2)*r with
 * r = √2,  s = r/(r-1) = 2+√2.  The set is generated by repeatedly
 * taking floor(r·n) and floor(s·n).  Here we generate the sequence in
 * ascending order by a priority‑queue (min‑heap).  The algorithm uses
 * only integer arithmetic: floor(r·n) is computed as
 *   floor(√2·n) = floor(sqrt(2·n²))
 * and floor(s·n) = floor(r·n) + 2·n.
 * The code is completely deterministic, memoises generated terms,
 * and works for any build where seq_t is an unsigned integer type or an
 * arbitrary‑precision integer class providing the operations used. */

#include <stdlib.h>
#include <stdbool.h>
#include <stddef.h>
#include "../utils/floor_sqrt.h"     /* seq_t floor_sqrt(seq_t) */

/* ----- Simple dynamic array for seq_t values ----- */
typedef struct {
    seq_t *data;
    size_t size;
    size_t capacity;
} vec_t;

static void vec_init(vec_t *v, size_t init_cap) {
    v->capacity = init_cap > 0 ? init_cap : 4;
    v->size = 0;
    v->data = (seq_t *)malloc(v->capacity * sizeof(seq_t));
}
static void vec_push(vec_t *v, seq_t val) {
    if (v->size == v->capacity) {
        v->capacity <<= 1;
        v->data = (seq_t *)realloc(v->data, v->capacity * sizeof(seq_t));
    }
    v->data[v->size++] = val;
}
static seq_t vec_at(const vec_t *v, idx_t idx) {
    return v->data[idx];
}

/* ----- Min‑heap for seq_t values ----- */
typedef struct {
    seq_t *data;
    size_t size;
    size_t capacity;
} heap_t;

static void heap_init(heap_t *h, size_t init_cap) {
    h->capacity = init_cap > 0 ? init_cap : 4;
    h->size = 0;
    h->data = (seq_t *)malloc(h->capacity * sizeof(seq_t));
}
static void heap_push(heap_t *h, seq_t val) {
    if (h->size == h->capacity) {
        h->capacity <<= 1;
        h->data = (seq_t *)realloc(h->data, h->capacity * sizeof(seq_t));
    }
    size_t i = h->size++;
    h->data[i] = val;
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (h->data[p] <= h->data[i]) break;
        seq_t tmp = h->data[p];
        h->data[p] = h->data[i];
        h->data[i] = tmp;
        i = p;
    }
}
static seq_t heap_pop(heap_t *h) {
    seq_t top = h->data[0];
    h->size--;
    h->data[0] = h->data[h->size];
    size_t i = 0;
    while (1) {
        size_t l = i * 2 + 1;
        if (l >= h->size) break;
        size_t r = l + 1;
        size_t smallest = l;
        if (r < h->size && h->data[r] < h->data[l]) smallest = r;
        if (h->data[i] <= h->data[smallest]) break;
        seq_t tmp = h->data[i];
        h->data[i] = h->data[smallest];
        h->data[smallest] = tmp;
        i = smallest;
    }
    return top;
}

/* --------- Main sequence function --------- */
seq_t a(idx_t n) {
    static bool init = false;
    static vec_t seq;
    static heap_t heap;

    if (!init) {
        heap_init(&heap, 4);
        vec_init(&seq, 4);
        /* seed the tree with 2 */
        heap_push(&heap, (seq_t)2);
        init = true;
    }

    /* Generate terms until the requested index is available */
    while (seq.size < n) {
        seq_t cur = heap_pop(&heap);
        vec_push(&seq, cur);

        /* child 1: floor(r * cur) = floor( sqrt(2) * cur ) */
        seq_t prod = cur * cur;
        prod = prod * ((seq_t)2);
        seq_t child1 = floor_sqrt(prod);
        if (child1 != cur) {           /* avoid infinite loop on cur=2 */
            heap_push(&heap, child1);
        }

        /* child 2: floor(s * cur) = child1 + 2 * cur  (s = 2 + √2) */
        seq_t child2 = child1 + ((seq_t)2) * cur;
        heap_push(&heap, child2);
    }

    return vec_at(&seq, n - 1);
}
